using System.Text.Json.Serialization;

namespace NaviDnD.Data.Models;

// Location block 20×15 in the field grid MapConfig.MaxSize×MaxSize (MapConfig.Chunks). The geometry of the
// block is generated by the code (ChunkGenerator), the AI only fills it with creatures and objects
// (PopulateChunk).) The set of location blocks is set by the AI as a plan at the beginning of the game
// (plan_location → LocationGrower.CreatePlanned): the geometry of all blocks is built at once, filling is done
// when the hero approaches the block.
public class MapChunk
{
    public const int Cols = 20;
    public const int Rows = 15;
    public const int GridCols = MapConfig.MaxSize / Cols; // 5
    public const int GridRows = MapConfig.MaxSize / Rows; // 6

    public int X { get; set; }               // horizontal block index, 0..GridCols-1
    public int Y { get; set; }               // vertical block index (map lines grow upward), 0..GridRows-1
    public int Seed { get; set; }
    public string Theme { get; set; } = "dungeon";
    public List<ChunkExit> Exits { get; set; } = [];
    public bool Populated { get; set; }      // AI has already placed creatures/objects
    public string? Purpose { get; set; }     // assignment of a block according to the location plan (which is according to the plot here)

    // Terrain of an open area (OutdoorGenerator): Rows lines according to Cols codes TerrainCatalog, line 0 -
    // bottom (OriginRow+1). null - block of rooms (dungeon). Space - emptiness.
    public List<string>? Terrain { get; set; }

    // Floor: 0 - ground, 1+ - upper floors, −1... - basements. The floors of one building stand on top of each
    // other in plan, and on the field they lie in different places on the grid; Only the hero's floor is
    // visible on the screen.
    public int Z { get; set; }

    // The top floor of the building: the grid cell of the first floor block below it - the view from the
    // windows to the outside (yard, street) is drawn according to the map of the first floor
    // (MapObjectsProvider.ApplyOutsideView).
    public int? GroundX { get; set; }
    public int? GroundY { get; set; }

    public static bool IsOutdoorTheme(string? theme) => theme is "forest" or "plains" or "hills" or "mountain" or "swamp" or "desert" or "snow" or "taiga";

    // Building: rooms close to each other with common walls, doors between them, furniture (BuildingGenerator).
    public const string Building = "building";

    // Settlement: several houses, streets, a square with a well, vegetable gardens (BuildingGenerator.GenerateVillage).
    public const string Village = "village";

    // Land in the open air with a passage along the edge without obstacles: terrain, courtyard of a building, settlement.
    public static bool IsOpenGround(string? theme) => IsOutdoorTheme(theme) || theme is Building or Village;

    // Type of building (building): tavern, house, shop, temple, manor, barracks, tower... - layout and furniture according to it.
    public string? Style { get; set; }

    // Natural cave: rooms-halls without tiles and doors (dungeon - man-made: crypt, ruins, fortress).
    public const string Cave = "cave";

    // Cell (OriginCol+1, OriginRow+1) - lower left cell of the block.
    [JsonIgnore] public int OriginCol => X * Cols;
    [JsonIgnore] public int OriginRow => Y * Rows;

    public bool Contains(int col, int row) =>
        col > OriginCol && col <= OriginCol + Cols && row > OriginRow && row <= OriginRow + Rows;
}

public enum ChunkSide { Left, Right, Bottom, Top }

// Exit on the edge of the block: seam in the Offset cell along the side (1..Rows for Left/Right, 1..Cols for
// Bottom/Top). The adjacent block receives an entrance on the opposite side in the same Offset - corridors
// converge across the border. External - entrance from outside (where the hero came from at the beginning of
// the game): behind it there are no blocks.
public class ChunkExit
{
    public ChunkSide Side { get; set; }
    public int Offset { get; set; }
    public bool External { get; set; }

    public static ChunkSide Opposite(ChunkSide side) => side switch
    {
        ChunkSide.Left => ChunkSide.Right,
        ChunkSide.Right => ChunkSide.Left,
        ChunkSide.Bottom => ChunkSide.Top,
        _ => ChunkSide.Bottom,
    };

    public static (int dx, int dy) Step(ChunkSide side) => side switch
    {
        ChunkSide.Left => (-1, 0),
        ChunkSide.Right => (1, 0),
        ChunkSide.Bottom => (0, -1),
        _ => (0, 1),
    };

    // The last cell of the exit corridor inside the block (in field coordinates).
    public (int col, int row) AnchorCell(MapChunk chunk) => Side switch
    {
        ChunkSide.Left => (chunk.OriginCol + 1, chunk.OriginRow + Offset),
        ChunkSide.Right => (chunk.OriginCol + MapChunk.Cols, chunk.OriginRow + Offset),
        ChunkSide.Bottom => (chunk.OriginCol + Offset, chunk.OriginRow + 1),
        _ => (chunk.OriginCol + Offset, chunk.OriginRow + MapChunk.Rows),
    };
}
